CREATE OR ALTER PROCEDURE dbo.GetRecentOrders
  @CustomerId int,
  @SinceDate  datetime2
AS
SELECT TOP (50)
    o.OrderId, o.OrderDate, o.Status, o.TotalAmount
FROM dbo.Orders AS o
WHERE o.CustomerId = @CustomerId
  AND o.OrderDate >= @SinceDate
ORDER BY o.OrderDate DESC;

